// Native parity port of web/src/hooks/useBreadcrumbs.ts.
//
// The web hook builds a breadcrumb trail for the current route by matching the
// browser URL (react-router-dom useLocation/useParams/matchPath) against the
// declarative ROUTE_META map (web/src/lib/routeMeta.ts, itself derived from the
// autogenerated ROUTE_REGISTRY) and walking each route's parent chain, then
// resolving labels via react-i18next. It returns BreadcrumbItem[] (the type
// lives in web/src/components/layout/Breadcrumbs.tsx).
//
// Per-import native adaptation:
//   - react useMemo (web L1) -> react useMemo + useCallback (kept).
//   - react-router-dom useLocation/useParams/matchPath (web L2) -> apps/native
//     ships no react-router and the shell (AppRoot.tsx) is a flat activeRoute
//     switch with no URL pathname or route params. The current pathname +
//     params are therefore supplied by the caller via an optional `source`, and
//     matchPath({path, end: true}) exact matching is reimplemented natively in
//     matchRoutePattern(). With no source the hook returns [] — the same value
//     the web hook returns for unknown / chrome-less routes.
//   - react-i18next useTranslation (web L3) -> native-safe t(key, fallback)
//     that returns the English fallback (defaultLabel), preserving i18n intent.
//   - type BreadcrumbItem from @/components/layout/Breadcrumbs (web L4) and
//     ROUTE_META/RouteMeta from @/lib/routeMeta (web L5) -> inlined native-safe
//     types; neither module is ported to apps/native yet, so ROUTE_META is an
//     injectable map (BreadcrumbRouteMetaMap) rather than a hard import.
//
// No DOM / react-router-dom / react-i18next / Recharts / Leaflet / web-UI
// imports are introduced.

import {useCallback, useMemo} from 'react';

/**
 * Breadcrumb item (web @/components/layout/Breadcrumbs `BreadcrumbItem`).
 */
export interface BreadcrumbItem {
  label: string;
  /** undefined = current page (no link). */
  href?: string;
}

/**
 * Route metadata for a single registered route (web @/lib/routeMeta
 * `RouteMeta`). A `parent` opts the route into a multi-item breadcrumb chain.
 */
export interface RouteMeta {
  /** i18n key for the human-readable label (falls back to `defaultLabel`). */
  i18nKey: string;
  /** Stable English label used as the i18n fallback. */
  defaultLabel: string;
  /** Parent route pattern; the hook walks this chain to compose the trail. */
  parent?: string;
}

/**
 * Declarative route-pattern -> RouteMeta map (web `ROUTE_META`). Keyed by the
 * react-router pattern (e.g. `/drives/:id`); iteration order decides which
 * pattern wins when several match, mirroring the web `Object.keys` scan.
 */
export type BreadcrumbRouteMetaMap = Readonly<Record<string, RouteMeta>>;

type RouteParams = Readonly<Record<string, string | undefined>>;

/**
 * Current-route input for the breadcrumb builder (web useLocation/useParams).
 * `params` is optional: when omitted the params parsed from matching `pathname`
 * against the winning route pattern are used (react-router's useParams returns
 * exactly those params for the active route).
 */
export interface BreadcrumbLocation {
  pathname: string;
  params?: RouteParams;
}

/**
 * Source for {@link useBreadcrumbs}: the active route metadata map plus the
 * current location. apps/native has no URL router, so a navigation layer must
 * supply this (or leave it undefined for the documented unavailable state).
 */
export interface BreadcrumbSource {
  routeMeta: BreadcrumbRouteMetaMap;
  location: BreadcrumbLocation;
}

type NativeTFunction = (key: string, fallback: string) => string;

/**
 * Why useBreadcrumbs returns an empty trail by default on React Native.
 */
export const BREADCRUMBS_NATIVE_ROUTER_UNAVAILABLE_REASON =
  'React Native ships no react-router-dom and the apps/native shell (AppRoot.tsx) is a flat activeRoute switch with no URL pathname, route params, or ported ROUTE_META; without a caller-supplied BreadcrumbSource useBreadcrumbs has no current route to resolve and returns an empty trail, matching the web hook empty-array result for unknown / chrome-less routes.';

// ---- Native-safe i18n fallback (web react-i18next useTranslation) -----------

function useNativeTranslationFallback(): NativeTFunction {
  return useCallback((_key: string, fallback: string) => fallback, []);
}

// ---- Native-safe exact route matching (web react-router-dom matchPath) -------

function safeDecode(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

/**
 * Native reimplementation of `matchPath({path: pattern, end: true}, pathname)`.
 * Returns the parsed params when `pattern` matches the whole `pathname`, else
 * null. Mirrors react-router v6 defaults: a `:param` segment captures a single
 * non-empty, URI-decoded segment; literal segments compare case-insensitively;
 * a trailing slash is ignored.
 */
export function matchRoutePattern(
  pattern: string,
  pathname: string,
): {params: Record<string, string>} | null {
  const patternSegments = pattern.split('/').filter(Boolean);
  const pathSegments = pathname.split('/').filter(Boolean);
  if (patternSegments.length !== pathSegments.length) {
    return null;
  }

  const params: Record<string, string> = {};
  for (let i = 0; i < patternSegments.length; i++) {
    const patternSegment = patternSegments[i];
    const pathSegment = pathSegments[i];
    if (patternSegment.startsWith(':')) {
      if (!pathSegment) {
        return null;
      }
      params[patternSegment.slice(1)] = safeDecode(pathSegment);
    } else if (patternSegment.toLowerCase() !== pathSegment.toLowerCase()) {
      return null;
    }
  }
  return {params};
}

// ---- Pure breadcrumb builder (web useBreadcrumbs useMemo body) ---------------

/**
 * Build breadcrumb items for `location` from `routeMeta`, faithfully porting
 * the web `useBreadcrumbs` useMemo body: find the first route pattern that
 * exactly matches the pathname, walk its parent chain (with cycle break),
 * resolve each label (page override > i18n key > default), substitute
 * `{{param}}` placeholders in labels and `:param` placeholders in hrefs, and
 * `unshift` so the trail reads root -> current with the current (leaf) item
 * left unlinked. Returns [] for unknown routes.
 */
export function buildBreadcrumbs(
  routeMeta: BreadcrumbRouteMetaMap,
  location: BreadcrumbLocation,
  overrides: Partial<Record<string, string>> | undefined,
  t: NativeTFunction,
): BreadcrumbItem[] {
  const path = location.pathname;

  // Find which route pattern matches the current path. Iterate registered
  // patterns and pick the first exact match.
  let matchedPattern: string | undefined;
  let matchedParams: RouteParams | undefined;
  for (const pattern of Object.keys(routeMeta)) {
    const match = matchRoutePattern(pattern, path);
    if (match) {
      matchedPattern = pattern;
      // Prefer caller-supplied params (web useParams), else the params parsed
      // from the matched pattern.
      matchedParams = location.params ?? match.params;
      break;
    }
  }
  if (!matchedPattern) {
    return [];
  }

  const params: RouteParams = matchedParams ?? {};
  const items: BreadcrumbItem[] = [];
  const visited = new Set<string>();
  let current: string | undefined = matchedPattern;

  while (current) {
    // Defensive: cycle break (the web routeMeta unit test also enforces this).
    if (visited.has(current)) {
      break;
    }
    visited.add(current);

    const meta: RouteMeta | undefined = routeMeta[current];
    if (!meta) {
      break;
    }

    // Resolve label: page-supplied override > i18n key > default label. The
    // native fallback t() returns `defaultLabel` directly, so missing
    // translations still render sensibly (i18n intent preserved).
    const override = overrides?.[current];
    let label: string = override ?? t(meta.i18nKey, meta.defaultLabel);

    // Substitute :param placeholders (e.g. "Drive #{{id}}").
    for (const [key, value] of Object.entries(params)) {
      if (value) {
        label = label.replace(`{{${key}}}`, value);
      }
    }

    // Compose href by replacing :params with concrete values.
    let href: string | undefined = current;
    for (const [key, value] of Object.entries(params)) {
      if (value) {
        href = href.replace(`:${key}`, value);
      }
    }

    items.unshift({
      label,
      // The trailing (current) item is plain text — no link.
      href: current === matchedPattern ? undefined : href,
    });

    current = meta.parent;
  }

  return items;
}

/**
 * Build breadcrumb items for the current route. (web/src/hooks/useBreadcrumbs.ts)
 *
 * On React Native there is no URL router, so a navigation layer supplies the
 * active route metadata + location via `source`; without it the hook returns []
 * (see {@link BREADCRUMBS_NATIVE_ROUTER_UNAVAILABLE_REASON}). Pages may still
 * pass per-render label `overrides` keyed by route pattern exactly as on web.
 *
 * Returns an empty array for unknown / chrome-less routes; a `<Breadcrumbs>`
 * surface also self-suppresses when there are <= 1 items, so top-level pages
 * render nothing without per-page wiring.
 */
export function useBreadcrumbs(
  overrides?: Partial<Record<string, string>>,
  source?: BreadcrumbSource | null,
): BreadcrumbItem[] {
  const t = useNativeTranslationFallback();

  return useMemo(() => {
    if (!source) {
      return [];
    }
    return buildBreadcrumbs(source.routeMeta, source.location, overrides, t);
  }, [source, overrides, t]);
}
